function editLibrary(kind,id){const list=kind==='camera'?p().cameras:p().lenses;editingLib={kind,id,draft:structuredClone(list.find(x=>x.id===id)||{}),provenance:{}};editingLib.provenance=structuredClone(editingLib.draft.provenance||{});go(kind)}
