function drawAsset(){const c=$('assetCanvas');if(!c)return;let w,h;if(screenSettings.aspect==='CUSTOM'){w=screenSettings.width;h=screenSettings.height;if(!Number.isInteger(w)||!Number.isInteger(h)||w<64||h<64||w>4096||h>4096){$('assetSize').textContent=tr('Use whole dimensions between 64 and 4096 px.');screenBlob=null;return}}else{const [a,b]=screenSettings.aspect.split(':').map(Number);w=a>=b?1920:Math.round(1920*a/b);h=a>=b?Math.round(1920*b/a):1920}c.width=w;c.height=h;const ctx=c.getContext('2d'),green=screenSettings.color==='GREEN';ctx.fillStyle=green?'#00b83c':'#0648e8';ctx.fillRect(0,0,w,h);ctx.strokeStyle=green?'#007c2a':'#12329a';ctx.lineWidth=Math.max(3,Math.min(w,h)*.006);const points=[],a=.13,b=.87;if(['4CORNERS','5POINT'].includes(screenSettings.pattern))points.push([a,a],[b,a],[a,b],[b,b]);if(screenSettings.pattern==='5POINT')points.push([.5,.5]);if(screenSettings.pattern==='GRID')for(let x=1;x<6;x++)for(let y=1;y<4;y++)points.push([x/6,y/4]);const len=Math.min(w,h)*.022;for(const [x,y] of points){ctx.beginPath();ctx.moveTo(w*x-len,h*y);ctx.lineTo(w*x+len,h*y);ctx.moveTo(w*x,h*y-len);ctx.lineTo(w*x,h*y+len);ctx.stroke()}$('assetSize').textContent=w+' × '+h+tr(' px · chroma-family tracking points');const version=++assetVersion;screenBlob=null;c.toBlob(b=>{if(version===assetVersion)screenBlob=b},'image/png')}
