function distortionScreen(){
 const c=raw()?.camera||{};
 $('main').innerHTML=pageTop(tr('Lens distortion'),tr('Tools'))+ui('<div class="asset-workspace"><section class="asset-controls"><p class="helper">A square-cell calibration grid with a center crosshair. Save or share it as an image.</p>')+selectField('gridAspect',tr('Aspect'),[['16:9','16:9'],['9:16','9:16'],['4:3','4:3'],['1:1','1:1'],['CUSTOM',tr('Custom')]],gridSettings.aspect,'onchange="gridSettings.aspect=this.value;document.getElementById(\'gridCustom\').hidden=this.value!==\'CUSTOM\';drawDistortion()"')+'<div id="gridCustom" '+(gridSettings.aspect==='CUSTOM'?'':'hidden')+'>'+field('gridWidth',tr('Width / px'),gridSettings.width,'number','min="64" max="4096" step="1" onchange="gridSettings.width=Number(this.value);drawDistortion()"')+field('gridHeight',tr('Height / px'),gridSettings.height,'number','min="64" max="4096" step="1" onchange="gridSettings.height=Number(this.value);drawDistortion()"')+'</div>'+selectField('gridDensity',tr('Grid density'),[['12',t('12 cells across short side')],['18',t('18 cells across short side')],['24',t('24 cells across short side')]],gridSettings.density,'onchange="gridSettings.density=Number(this.value);drawDistortion()"')+'<div class="settings">'+[[tr('Camera'),cam(c.cameraId)],[tr('Lens'),lens(c.lensId)],[tr('Focal'),c.focal!=null?c.focal+' mm':'—'],[tr('Focus'),c.focus!=null?c.focus+' m':'—'],[tr('Sensor mode'),c.sensorMode||'—']].map(([k,v])=>'<div class="setting"><label>'+k+'</label><span style="max-width:65%;text-align:right">'+esc(v)+'</span></div>').join('')+ui('</div></section><section class="asset-output"><div class="preview-wrap"><canvas id="gridCanvas" aria-label="Lens distortion grid preview"></canvas></div><p class="helper" id="gridSize"></p><div class="button-stack"><button class="primary" onclick="fullscreenGrid()">Fullscreen</button><button class="secondary" onclick="shareGrid()">Share</button><button class="secondary" onclick="saveGrid()">Save PNG</button></div></section></div>');drawDistortion();
}
function printDistortion(){return saveGrid()}

function scaleScreen(){$('main').innerHTML=pageTop(tr('Scale references'),tr('Tools'))+ui('<p class="helper">100 mm reference with 10 mm divisions. Verify with a physical ruler after printing.</p>')+selectField('scalePaper',tr('Paper'),paperOptions.map(([v,label])=>[v,t(label)]),'A4')+'<div class="preview-wrap" style="padding:20px">'+scaleSVG()+ui('</div><button class="primary action" onclick="printScale()">Print / Save PDF</button>')}
function scaleSVG(){return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 110 35"><rect width="110" height="35" fill="white" stroke="none"/>'+Array.from({length:10},(_,i)=>'<rect x="'+(5+i*10)+'" y="8" width="10" height="10" fill="'+(i%2?'white':'black')+'" stroke="black" stroke-width=".3"/>').join('')+'<path d="M5 5v18M105 5v18" stroke="black" stroke-width=".3"/><text x="55" y="29" text-anchor="middle" fill="black" stroke="none" font-family="Arial" font-size="5">100 mm</text></svg>'}
function printScale(){preparePrint(ui('<h2>VFX Tools · Scale reference</h2><p>')+esc(p().code)+' · Print at actual size / 100%.</p><div style="width:110mm;height:35mm">'+scaleSVG()+'</div>',$('scalePaper').value)}
function exportScreen(){$('main').innerHTML='<section class="hero"><div class="eyebrow accent">'+esc(p().code)+ui(' / EXPORT</div><h1>Export</h1></section><div class="list">')+row(tr('Project report / PDF'),tr('All ')+shots().length+tr(' shots · camera states, notes & measurements'),"report('project')")+row(tr('Project JSON'),tr('Full structured project metadata'),"exportJSON()")+row(tr('Shot CSV'),tr('Camera states & acquisition counts'),"exportCSV()")+row(tr('Project backup'),tr('Metadata + original media in one file'),"exportBackup()")+(shot()?row(tr('Current shot / PDF'),shot().code+tr(' only'),"report('shot')"):'')+'</div>'+ui('<p class="footer-note">JSON and CSV contain metadata. Use project backup to include original photos and videos.</p>')}
async function report(scope='project'){
 if(reportBusy)return;const all=structuredClone(scope==='shot'?(shot()?[shot()]:[]):shots());if(!all.length)return toast(tr('Create a shot before exporting a report.'));reportBusy=true;const reportProject=structuredClone(p()),reportOperator=state.operator;toast(tr('Preparing PDF…'));
 try{for(const url of printURLs)URL.revokeObjectURL(url);printURLs=[];const header='<div class="report-heading"><img class="report-brand" src="./assets/vfx-tools-banner.png" alt="VFX Tools"><h1>'+esc(reportProject.name)+'</h1><p>VFX Tools · '+esc(reportProject.code)+' · '+all.length+' shots</p><p>'+esc(t('Operator'))+': '+esc(reportOperator||'—')+' · '+esc(new Date().toLocaleString(currentLanguage()))+'</p></div>';
 const parts=[];for(const h of all)parts.push(reportShotHTML(h,reportProject).replace('<div data-reference-images></div>',await reportReferences(h)));
 $('printRoot').innerHTML='<style>@page{size:A4;margin:12mm}</style>'+header+parts.join('');
 await Promise.all([...$('printRoot').querySelectorAll('img')].map(async img=>{try{await img.decode()}catch{const warning=document.createElement('p');warning.textContent=t('Image unavailable for this PDF. Original file remains in the project backup.');img.replaceWith(warning)}}));
 document.title=reportProject.code+'_'+(scope==='shot'?all[0].code:'ALL_SHOTS')+'_VFX_REPORT';window.print();
 }catch(error){toast(tr('Could not prepare the PDF. Please retry.'));console.error(error)}finally{reportBusy=false}
}
let reportBusy=false,printURLs=[];
async function reportReferences(h){const refs=[...(h.media||[]),...(h.plates||[])];if(!refs.length)return '<p>'+esc(t('None recorded.'))+'</p>';let html='<div class="report-references">';for(const m of refs){const entry=await get('media',m.mediaId),caption=t('Take')+' '+(m.take||1)+' · '+pretty(m.tag||m.type||'GENERAL')+(m.note?' · '+m.note:'');let content;if(!entry)content='<p>'+esc(t('Media file is unavailable on this device.'))+'</p>';else if(entry.kind==='video'||entry.type?.startsWith('video/'))content='<p>'+esc(t('Video · original included in project backup.'))+'</p>';else{const url=URL.createObjectURL(mediaBlob(entry));printURLs.push(url);content='<img src="'+url+'" alt="'+esc(t('Captured reference'))+'">'}html+='<figure>'+content+'<figcaption>'+esc(caption)+'</figcaption></figure>'}return html+'</div>'}

async function exportBackup(){toast(tr('Preparing backup with original media…'));const data=payload(),all=shots(data.project),ids=[...new Set(all.flatMap(h=>[...(h.media||[]),...(h.plates||[]),...(h.voice||[])].map(m=>m.mediaId)).filter(Boolean))];const media=[];for(const id of ids){const entry=await get('media',id);if(!entry){toast(tr('Backup stopped: a media file is missing.'));return}const encoded=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(mediaBlob(entry))});const {blob,bytes,...meta}=entry;media.push({...meta,data:encoded})}dl(data.project.code+'_VFX_BACKUP.json',new Blob([JSON.stringify({...data,backup_format:'slyhigh.media-backup.1',media})],{type:'application/json'}));toast(tr('Backup ready'))}
window.addEventListener('unhandledrejection',e=>{console.error(e.reason);setSaveStatus(tr('ACTION FAILED · RETRY'),true)});
async function init(){try{await openDB();await load();state.projects||=[];for(const pr of state.projects){pr.cameras||=[];pr.lenses||=[];pr.days||=[];for(const h of shots(pr)){// Fill absent collections on the stored object without replacing existing data.
for(const d of pr.days)for(const s of d.scenes)for(const u of s.setups){const r=u.shots.find(x=>x.id===h.id);if(r){for(const k of ['types','media','measurements','notes','plates','voice'])r[k]||=[];r.camera||={};r.take||=1;r.types=r.types.filter(Boolean)}}}}
route={page:p()?(shot()?'shot':'shoot'):'projects',projectId:state.activeProjectId,shotId:state.activeShotId};history.replaceState({sly:true},'');if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});render();setSaveStatus(tr('ON DEVICE'));updateLanguageControl();if(navigator.storage?.persist)navigator.storage.persist().catch(()=>{});window.visualViewport?.addEventListener('resize',()=>document.body.classList.toggle('keyboard',window.visualViewport.height<window.innerHeight*.75))}catch(e){$('main').innerHTML=ui('<section class="hero"><h1>Storage unavailable.</h1><p class="lead">Allow browser storage, then reload to open your projects.</p><button class="primary action" onclick="location.reload()">Retry</button></section>');console.error(e)}}init();


function renderCaptureDock(){let dock=$('captureDock');if(!dock){dock=document.createElement('div');dock.id='captureDock';document.body.append(dock)}const show=route.page==='shot'&&raw();document.body.classList.toggle('has-capture-dock',!!show);dock.hidden=!show;if(show)dock.innerHTML=ui('<span><small>CURRENT TAKE</small><b>')+String(raw().take||1).padStart(2,'0')+'</b></span><button class="primary" onclick="capture()">'+icon('camera')+ui(' Capture photo / video</button>')}

function localDate(){const d=new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,10)}
function ensureSetup(pr,date,scene,setup){let d=pr.days.find(x=>x.date===date);if(!d){const n=Math.max(0,...pr.days.map(x=>Number(x.code.replace(/\D/g,''))||0))+1;d={id:uid(),code:'DAY '+String(n).padStart(2,'0'),date,scenes:[]};pr.days.push(d)}let s=d.scenes.find(x=>x.code===scene);if(!s){s={id:uid(),code:scene,setups:[]};d.scenes.push(s)}let u=s.setups.find(x=>x.code===setup);if(!u){u={id:uid(),code:setup,shots:[]};s.setups.push(u)}return u}
async function updateShotDate(date){if(!/^\d{4}-\d{2}-\d{2}$/.test(date))return;const h=shot(),r=raw();if(date===h._d.date)return;const target=ensureSetup(p(),date,h._s.code,h._u.code);h._u.shots=h._u.shots.filter(x=>x.id!==r.id);target.shots.push(r);for(const d of p().days){for(const s of d.scenes)s.setups=s.setups.filter(u=>u.shots.length);d.scenes=d.scenes.filter(s=>s.setups.length)}p().days=p().days.filter(d=>d.scenes.length);await save();render();toast(tr('Shoot date updated'))}
function slateHeader(h,r){return ui('<section class="slate" aria-label="Shot slate"><div class="slate-production"><span class="eyebrow">PRODUCTION</span><b>')+esc(p().name)+'</b></div><div class="slate-grid"><div class="slate-shot">'+field('sh',tr('Shot'),h.code,'text','autocapitalize="characters" onchange="updateShotIdentity(\'code\',this)"')+'</div><div class="slate-cell">'+field('sc',tr('Scene'),h._s.code,'text','onchange="updateShotIdentity(\'scene\',this)"')+'</div><div class="slate-cell">'+field('su',tr('Setup'),h._u.code,'text','onchange="updateShotIdentity(\'setup\',this)"')+ui('</div><div class="slate-take"><span class="eyebrow accent">CURRENT TAKE</span><div class="take-controls"><button id="takeMinus" aria-label="Previous take" onclick="take(-1)" ')+(r.take<=1?'disabled':'')+'>−</button><strong id="takeNumber" aria-live="polite">'+String(r.take||1).padStart(2,'0')+ui('</strong><button aria-label="Next take" onclick="take(1)">+</button></div></div></section>')+(r.inherited_from?'<p class="helper inherited-info">'+esc(t('Camera settings inherited from'))+' '+esc(shots().find(x=>x.id===r.inherited_from)?.code||'—')+ui('. <button class="text-button" onclick="clearInherited()">Clear inherited values</button></p>'):'')}
async function updateShotIdentity(key,input){const h=shot(),r=raw(),value=input.value.trim().toUpperCase();if(key==='code'){if(!value||shots().some(x=>x.id!==h.id&&x.code===value)){input.value=h.code;return toast(tr('Use a unique, non-empty shot name.'))}r.code=value}else{const target=ensureSetup(p(),h._d.date,key==='scene'?value:h._s.code,key==='setup'?value:h._u.code);if(target.id!==h._u.id){h._u.shots=h._u.shots.filter(x=>x.id!==h.id);target.shots.push(r);pruneEmptySetups()}}input.value=value;await save()}
function pruneEmptySetups(){for(const d of p().days){for(const s of d.scenes)s.setups=s.setups.filter(u=>u.shots.length);d.scenes=d.scenes.filter(s=>s.setups.length)}p().days=p().days.filter(d=>d.scenes.length)}
async function clearInherited(){const r=raw();for(const [key,source] of Object.entries(r.cameraProvenance||{}))if(source==='INHERITED'){r.camera[key]=null;r.cameraProvenance[key]='EMPTY'}delete r.inherited_from;syncShutter(r.camera);await save();render()}

function shotTypeFields(types=[]){return [...types,...(route.addingType?['']:[])].map((v,i)=>'<div class="type-row">'+selectField('shotType_'+i,tr('Shot type'),[['',tr('Select type')],...TYPES.map(t=>[t,pretty(t)])],v,'onchange="changeShotType('+i+',this.value)"')+'<button class="remove-type" type="button" aria-label="'+esc(t('Remove type')+' '+(i+1))+'" onclick="removeShotType('+i+')">−</button></div>').join('')+ui('<button type="button" class="secondary add-type" onclick="addShotType()">+ Add type</button>')}
function addShotType(){route.addingType=true;$('shotTypes').innerHTML=shotTypeFields(raw().types);$('shotType_'+raw().types.length).focus()}
async function removeShotType(index){if(index<raw().types.length){raw().types.splice(index,1);await save()}else route.addingType=false;$('shotTypes').innerHTML=shotTypeFields(raw().types)}
async function changeShotType(index,value){const types=raw().types;if(value&&types.some((v,i)=>i!==index&&v===value))toast(t('This type is already selected.'));else{if(value)types[index]=value;else types.splice(index,1);route.addingType=false;await save()}$('shotTypes').innerHTML=shotTypeFields(types)}

const SHUTTER_ANGLES=[360,180,172.8,144,90,45],SHUTTER_FRACTIONS=[24,25,30,47.952,48,50,60,96,100,120,125,250,500,1000,2000];
const compactNumber=v=>v==null?'':Number(Number(v).toFixed(6)).toString();
function syncShutter(c){const fps=Number(c.fps);if(!(fps>0)){if(c.shutterMode==='fraction')c.shutter=null;else c.shutterFraction=null;return}if(c.shutterMode==='fraction')c.shutter=c.shutterFraction>0?360*fps/c.shutterFraction:null;else c.shutterFraction=c.shutter>0?360*fps/c.shutter:null}
function shutterControls(){const c=raw().camera||{},fraction=c.shutterMode==='fraction',value=fraction?c.shutterFraction:c.shutter,presets=fraction?SHUTTER_FRACTIONS:SHUTTER_ANGLES,known=presets.find(v=>Math.abs(v-value)<1e-8),selected=value==null?'':known!==undefined?String(known):'custom';return ui('<div class="shutter-head"><label for="shutterValue">Shutter<small>')+t(provenance(raw(),fraction?'shutterFraction':'shutter'))+ui('</small></label><div class="segmented" aria-label="Shutter representation"><button type="button" aria-pressed="')+!fraction+ui('" onclick="setShutterMode(\'angle\')">Angle °</button><button type="button" aria-pressed="')+fraction+ui('" onclick="setShutterMode(\'fraction\')">Fraction 1/s</button></div></div><div class="field shutter-value"><select id="shutterValue" aria-label="Shutter value" onchange="selectShutter(this.value)">')+opt('','',selected)+presets.map(v=>opt(v,fraction?'1/'+v+' s':v+'°',selected)).join('')+opt('custom',tr('Custom'),selected)+'</select></div><div id="shutterCustomWrap" '+(selected==='custom'?'':'hidden')+'>'+field('shutterCustom',fraction?tr('Denominator · exposure is 1 / value seconds'):tr('Angle / degrees'),selected==='custom'?compactNumber(value):'','number','min="0.000001" step="any" onchange="updateShutter(this.value)"')+'</div><p class="helper shutter-helper" id="shutterEquivalent">'+shutterEquivalent(c)+'</p>'}
function shutterEquivalent(c){if(!(Number(c.fps)>0))return tr('Set FPS to calculate the equivalent angle or fraction.');if(c.shutterMode==='fraction'&&c.shutterFraction>0)return tr('Equivalent ')+compactNumber(c.shutter)+'° '+t('at')+' '+c.fps+' fps';if(c.shutter>0)return t('Equivalent')+' 1/'+compactNumber(360*c.fps/c.shutter)+' s '+t('at')+' '+c.fps+' fps';return tr('Choose a shutter value.')}
async function setShutterMode(mode){const c=raw().camera,current=c.shutterMode==='fraction'?c.shutterFraction:c.shutter;if(mode!==(c.shutterMode||'angle')&&current>0&&!(Number(c.fps)>0))return toast(tr('Set FPS before converting shutter units.'));syncShutter(c);c.shutterMode=mode;syncShutter(c);$('shutterControl').innerHTML=shutterControls();await save()}
async function selectShutter(v){if(v==='custom'){$('shutterCustomWrap').hidden=false;$('shutterCustom').focus();return}await updateShutter(v);$('shutterControl').innerHTML=shutterControls()}
async function updateShutter(value){const h=raw(),c=h.camera,fraction=c.shutterMode==='fraction',n=value===''?null:Number(value);if(n!==null&&(!Number.isFinite(n)||n<=0||(!fraction&&n>360)))return toast(fraction?tr('Enter a positive denominator.'):tr('Use an angle greater than 0 and up to 360°.'));c[fraction?'shutterFraction':'shutter']=n;h.cameraProvenance||={};h.cameraProvenance.shutter=h.cameraProvenance.shutterFraction=n===null?'EMPTY':'USER ENTERED';syncShutter(c);c.updated=now();await save();$('shutterEquivalent').textContent=shutterEquivalent(c)}
const navObserver=new ResizeObserver(()=>{if(!$('nav').hidden)document.documentElement.style.setProperty('--nav-height',$('nav').getBoundingClientRect().height+'px')});navObserver.observe($('nav'));

let gridSettings={aspect:'16:9',width:3840,height:2160,density:18},gridBlob=null,gridVersion=0;
function drawDistortion(){const canvas=$('gridCanvas');if(!canvas)return;let w=gridSettings.width,h=gridSettings.height;if(gridSettings.aspect!=='CUSTOM'){const [a,b]=gridSettings.aspect.split(':').map(Number);w=a>=b?3840:Math.round(3840*a/b);h=a>=b?Math.round(3840*b/a):3840}const version=++gridVersion;gridBlob=null;if(!Number.isInteger(w)||!Number.isInteger(h)||w<64||h<64||w>4096||h>4096){$('gridSize').textContent=tr('Use whole dimensions from 64 to 4096 px.');return}canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d'),step=Math.min(w,h)/gridSettings.density;ctx.fillStyle='#fff';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#000';ctx.lineWidth=Math.max(1,Math.min(w,h)/700);ctx.beginPath();for(let i=-Math.ceil(w/step/2);i<=Math.ceil(w/step/2);i++){const x=w/2+i*step;ctx.moveTo(x,0);ctx.lineTo(x,h)}for(let i=-Math.ceil(h/step/2);i<=Math.ceil(h/step/2);i++){const y=h/2+i*step;ctx.moveTo(0,y);ctx.lineTo(w,y)}ctx.stroke();ctx.lineWidth*=3;ctx.beginPath();ctx.arc(w/2,h/2,step*.28,0,Math.PI*2);ctx.moveTo(w/2-step*.5,h/2);ctx.lineTo(w/2+step*.5,h/2);ctx.moveTo(w/2,h/2-step*.5);ctx.lineTo(w/2,h/2+step*.5);ctx.stroke();$('gridSize').textContent=w+' × '+h+tr(' px · square cells · center crosshair');canvas.toBlob(b=>{if(version===gridVersion)gridBlob=b},'image/png')}
function gridName(){const c=raw()?.camera||{},canvas=$('gridCanvas');return [p().code,shot()?.code,'DISTORTION',c.focal!=null?'F'+compactNumber(c.focal)+'mm':null,canvas.width+'x'+canvas.height].filter(Boolean).join('_')+'.png'}
function saveGrid(){if(!gridBlob)return toast(tr('Wait for a valid grid preview.'));dl(gridName(),gridBlob)}
async function shareGrid(){if(!gridBlob)return toast(tr('Wait for a valid grid preview.'));const file=new File([gridBlob],gridName(),{type:'image/png'});try{if(navigator.canShare?.({files:[file]}))await navigator.share({files:[file],title:'VFX Tools · Lens distortion'});else{saveGrid();toast(tr('Sharing unavailable. PNG saved instead.'))}}catch(e){if(e.name!=='AbortError'){saveGrid();toast(tr('PNG saved instead.'))}}}
function fullscreenGrid(){if(gridBlob)showCanvasFullscreen($('gridCanvas'),'#fff')}
function showCanvasFullscreen(source,background){const overlay=document.createElement('div');overlay.className='full-asset';overlay.style.background=background;overlay.id='assetFullscreen';const canvas=document.createElement('canvas');canvas.width=source.width;canvas.height=source.height;canvas.getContext('2d').drawImage(source,0,0);overlay.append(canvas);const exit=document.createElement('button');exit.textContent=tr('Exit fullscreen');exit.onclick=closeFullscreen;overlay.append(exit);document.body.append(overlay);overlay.requestFullscreen?.().catch(()=>{});exit.focus()}
function shutterSeconds(c){if(c.shutterMode==='fraction')return c.shutterFraction>0?1/c.shutterFraction:null;return c.shutter>0&&c.fps>0?c.shutter/(360*c.fps):null}
function reportShotHTML(h,project=p()){
 const c=h.camera||{},equipment=(list,id)=>{const item=list.find(x=>x.id===id);return item?[item.code,item.make,item.model].filter(Boolean).join(' · '):'—'};
 const shutter=c.shutterMode==='fraction'?(c.shutterFraction?'1/'+compactNumber(c.shutterFraction)+' s':'—'):(c.shutter!=null?compactNumber(c.shutter)+'°':'—');
 const fields=[['Camera',equipment(project.cameras,c.cameraId)],['Lens',equipment(project.lenses,c.lensId)],['Focal / mm',c.focal],['Focus / m',c.focus],['T / F stop',c.aperture],['EI / ISO',c.ei],['White balance / K',c.wb],['FPS',c.fps],['ND',c.nd],['Shutter',shutter],['Movement',c.movement?pretty(c.movement):null],['Sensor mode',c.sensorMode],['Color / gamma',c.color]];
 let table='';for(let i=0;i<fields.length;i+=2){table+='<tr>';for(const entry of fields.slice(i,i+2))table+='<th>'+esc(t(entry[0]))+'</th><td>'+esc(entry[1]??'—')+'</td>';if(!fields[i+1])table+='<th></th><td></td>';table+='</tr>'}
 return '<section class="report-shot" data-shot-id="'+esc(h.id)+'"><h2>'+esc(h.code)+'</h2><p>'+esc(h._d.date)+' · '+t('SC')+' '+esc(h._s.code||'—')+' · SETUP '+esc(h._u.code||'—')+' · '+t('TAKE')+' '+esc(h.take)+'</p><p>'+h.types.filter(Boolean).map(type=>esc(pretty(type))).join(' · ')+'</p><table class="report-camera">'+table+'</table><h3>'+t('Measurements')+'</h3>'+(h.measurements.length?'<table>'+h.measurements.map(m=>'<tr><td>'+t('Take')+' '+esc(m.take)+'</td><td>'+esc(m.from)+' → '+esc(m.to)+'</td><td>'+esc(m.value)+' '+esc(m.unit)+'</td><td>'+esc(pretty(m.method))+' / '+esc(pretty(m.confidence))+'</td></tr>').join('')+'</table>':'<p>'+t('None recorded.')+'</p>')+'<h3>'+t('Notes')+'</h3>'+(h.notes.map(n=>'<p><b>'+t('TAKE')+' '+esc(n.take)+'</b> '+esc(n.text)+'</p>').join('')||'<p>'+t('None recorded.')+'</p>')+'<h3>'+t('References')+'</h3><div data-reference-images></div></section>'
}
